package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject.MetadataVO;

class MetadataValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of metadata of tenant login provider")
  void test_metadata_value_holder_assign_plain_value() {
    Object holder = new Object();
    MetadataValueHolder<Object> value = new MetadataValueHolder<>(holder);
    Assertions.assertSame(holder, value.metadata("file_1"), "Setters must return the holder");
    Assertions.assertTrue(value.getMetadataValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("file_1", value.getMetadata().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.metadataNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getMetadataValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getMetadata().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of metadata of tenant login provider")
  void test_metadata_value_holder_assign_value_object() {
    Object holder = new Object();
    MetadataValueHolder<Object> value = new MetadataValueHolder<>(holder);
    MetadataVO vo = MetadataVO.from("file_1");
    Assertions.assertFalse(value.getMetadataValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.metadata(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getMetadataValue().orElseThrow());
    Assertions.assertSame(holder, value.metadata(Optional.empty()));
    Assertions.assertFalse(value.getMetadataValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.metadata(Optional.of(vo)));
    Assertions.assertSame(vo, value.getMetadataValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of metadata of tenant login provider against the original")
  void test_metadata_value_holder_read() {
    Object holder = new Object();
    MetadataValueHolder<Object> value = new MetadataValueHolder<>(holder);
    MetadataVO vo = MetadataVO.from("file_1");
    MetadataVO other = MetadataVO.from("file_1");
    TenantLoginProvider original = Mockito.mock(TenantLoginProvider.class);
    Mockito.when(original.getMetadataValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readMetadata(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readMetadata(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.metadata(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readMetadata(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readMetadata(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of metadata of tenant login provider")
  void test_metadata_value_holder_unset() {
    Object holder = new Object();
    MetadataValueHolder<Object> value = new MetadataValueHolder<>(holder);
    MetadataVO vo = MetadataVO.from("file_1");
    value.metadata(vo);
    Assertions.assertSame(holder, value.unsetMetadataIfMatches("metadata_other"));
    Assertions.assertTrue(value.getMetadataValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetMetadataIfMatches("metadata"));
    Assertions.assertFalse(value.getMetadataValue().isPresent(),
        "The field name must clear the value");
    value.metadata(vo);
    Assertions.assertSame(holder, value.unsetMetadata());
    Assertions.assertFalse(value.getMetadataValue().isPresent(), "Unset must clear the value");
  }
}
